import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

const Example = (args: { type: "success" | "info" | "warning" | "error"; description: string }) => (
  <Button
    variant={args.type}
    onClick={() => {
      void toast.add({
        description: args.description,
        id: `toast-playground-${args.type}`,
        type: args.type,
      });
    }}
  >
    Show toast
  </Button>
);

export default Example;
